  label.className = "checkbox-label";
  label.innerHTML = `I have read and agree to the
    <a href="#" onclick="return false;">Terms of Use</a>
    and <a href="#" onclick="return false;">Privacy Policy</a>.`;

  const helper = document.createElement("span");
  helper.className = "helper-text";
  helper.id = "consent-helper";
  helper.textContent =
    "You must accept the terms to create an account and use our services.";

  labelGroup.appendChild(label);
  labelGroup.appendChild(helper);

  wrapper.appendChild(checkbox);
  wrapper.appendChild(labelGroup);

  // Inline error message
  const error = document.createElement("span");
  error.className = "field-error";
  error.id = "consent-error";
  error.setAttribute("role", "alert");
  error.innerHTML = `
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none"
         stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
      <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/>
      <line x1="12" y1="16" x2="12.01" y2="16"/>
    </svg>
    Please accept the Terms of Use to continue.`;

  field.appendChild(wrapper);
  field.appendChild(error);

  // Sync checked state to wrapper style
  function syncState() {
    wrapper.classList.toggle("checked", checkbox.checked);
  }

  // Validate and surface/clear error
  function validate() {
    const valid = checkbox.checked;
    field.classList.toggle("invalid", !valid);
    error.classList.toggle("visible", !valid);
