  return banner;
}

function ConsentForm() {
  const form = document.createElement("form");
  form.className = "consent-form";
  form.noValidate = true;

  let isValid = false;
  const successBanner = SuccessBanner();
  const consentField = ConsentField({
    onValidationChange: (valid) => { isValid = valid; },
  });

  const submitBtn = document.createElement("button");
  submitBtn.type = "submit";
  submitBtn.className = "btn-submit";
  submitBtn.innerHTML = `
    Continue
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none"
         stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
      <line x1="5" y1="12" x2="19" y2="12"/>
      <polyline points="12 5 19 12 12 19"/>
    </svg>`;

  form.appendChild(consentField);
  form.appendChild(successBanner);
  form.appendChild(submitBtn);

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const valid = consentField._validate();
    if (!valid) return;

    // Show success, hide submit button
    successBanner.classList.add("visible");
    submitBtn.style.display = "none";
    submitBtn.setAttribute("aria-hidden", "true");
  });

  return form;
}

function App() {
  const card = document.createElement("div");
  card.className = "card";
  card.appendChild(CardHeader());
  card.appendChild(ConsentForm());
  return card;
}

// Mount
document.getElementById("root").appendChild(App());
